"""Twenty original sleep-disordered breathing questions."""
from qbank_authoring import question,ref,finalize
DX=ref('AASM: Diagnostic Testing for Adult OSA','https://pmc.ncbi.nlm.nih.gov/articles/PMC5337595/')
OH=ref('ATS: Evaluation and Management of Obesity Hypoventilation Syndrome','https://pmc.ncbi.nlm.nih.gov/articles/PMC6680300/')
CS=ref('AASM: Treatment of Central Sleep Apnea in Adults, 2025','https://aasm.org/wp-content/uploads/2026/02/central-sleep-apnea-guideline-AASM-2025.pdf')
TZ=ref('FDA: Tirzepatide Approval for OSA in Adults with Obesity','https://www.fda.gov/news-events/press-announcements/fda-approves-first-medication-obstructive-sleep-apnea')
PA=ref('AASM: PAP Treatment of Adult OSA','https://pmc.ncbi.nlm.nih.gov/articles/PMC6374094/')
OA=ref('AASM/AADSM: Oral Appliance Treatment of OSA','https://pmc.ncbi.nlm.nih.gov/articles/PMC4481062/')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('During a sleep study, airflow ceases while thoracoabdominal effort persists. Which event is most consistent?', 'Obstructive apnea',[
 ('Central apnea','Central apnea lacks respiratory effort during the event.'),('Sustained hypoventilation alone','This is a prolonged reduction in ventilation rather than the stated discrete obstructive event.'),('Periodic limb movement','This describes limb activity rather than absent airflow with effort.')],
 'Effort distinguishes obstruction from loss of central drive', '**Continued effort against a closed or markedly narrowed airway indicates obstruction.**',['Snoring and paradoxical movement can support the pattern.','Scoring also requires the specified airflow reduction and duration.'], '**Interpret the event burden across the study.**',['A single event does not define the overall syndrome or severity.','Symptoms and associated desaturation contribute to clinical assessment.'],[['Obstructive','Airflow absent, effort persists'],['Central','Airflow and effort absent'],['Mixed','Central and obstructive components']],[DX])
q('An overnight polysomnogram records 180 apneas and hypopneas over 6 hours of sleep. What is the AHI?', '30 events/hour',[
 ('15 events/hour','180 divided by 6 is 30.'),('60 events/hour','This doubles the calculated rate.'),('180 events/hour','That is the total count, not the hourly index.')],
 'AHI uses total sleep time as the denominator', '**AHI = scored apneas plus hypopneas divided by sleep hours.**',['Here 180 / 6 = 30.','Home studies may use recording time and report a respiratory event index instead.'], '**Do not confuse counts with rates.**',['Study quality and scoring definitions affect interpretation.','The clinical burden also includes symptoms and oxygenation.'],[['Events','180'],['Sleep time','6 hours'],['AHI','30/hour']],[DX])
q('Using conventional adult AHI severity bands, an AHI of 22 events/hour is classified as which severity?', 'Moderate',[
 ('Mild','Mild generally corresponds to 5 to less than 15.'),('Severe','Severe begins at 30.'),('Normal','22 is above the normal range.')],
 'Severity bands provide a common language but not a complete phenotype', '**Moderate OSA corresponds to AHI 15 to less than 30.**',['An index at least 30 is severe.','Symptoms and hypoxic burden can differ between patients with the same AHI.'], '**Integrate the number with the clinical assessment.**',['Evaluate sleepiness, comorbidity and driving risk.','Use the findings to support an individualized treatment discussion.'],[['Mild','5–<15'],['Moderate','15–<30'],['Severe','At least 30']],[DX])
q('A patient has loud snoring, witnessed apneas and daytime sleepiness. What is the role of STOP-Bang or a similar questionnaire?', 'Risk stratification to support evaluation, not definitive diagnosis without objective testing',[
 ('Confirmation of OSA in place of a sleep study','Questionnaires lack the required standalone diagnostic accuracy.'),('Measurement of overnight arterial CO2','They do not measure gas exchange.'),('Proof of a specific upper-airway collapse site','Anatomical localization requires different evaluation.')],
 'A screening tool is not the diagnostic endpoint', '**Symptoms and risk factors determine who needs further evaluation.**',['A high-risk score increases suspicion.','A score does not quantify the actual event burden.'], '**Use an appropriate objective test.**',['Choose home testing or polysomnography according to comorbidity and suspicion.','Investigate alternative causes of sleepiness when appropriate.'],[['Questionnaire','Risk assessment'],['Sleep test','Objective event measurement'],['Clinical review','Comorbidity and alternative explanations']],[DX],style='clinical_scenario')
q('An uncomplicated adult has a high likelihood of moderate-to-severe OSA and no suspected hypoventilation or significant cardiopulmonary disease. Which diagnostic option is reasonable?', 'A technically adequate home sleep apnea test within an appropriate diagnostic pathway',[
 ('Pulse oximetry alone as a definitive universal test','Oximetry alone cannot reliably characterize all respiratory events.'),('A normal daytime spirometry test as exclusion','Daytime spirometry does not rule out sleep-related upper-airway obstruction.'),('A questionnaire without objective testing','Risk tools alone do not establish the diagnosis.')],
 'Home testing is appropriate for selected uncomplicated patients', '**The device and interpretation must meet an adequate standard.**',['It should follow a comprehensive sleep assessment.','Its use is not interchangeable with testing for every sleep disorder.'], '**Complete the pathway if the result is negative or inadequate.**',['A negative study does not end a high-suspicion evaluation.','Polysomnography is then appropriate.'],[['Suitable patient','Uncomplicated with increased OSA risk'],['Home test','Adequate equipment and interpretation'],['Negative / inadequate','Proceed to PSG']],[DX],style='clinical_scenario')
q('A home sleep apnea study is technically adequate but negative despite persistent strong suspicion of OSA. What is recommended next?', 'Polysomnography',[
 ('Definitively exclude OSA','A negative home result can be false negative.'),('Repeat questionnaires until the score becomes low','This does not resolve the diagnostic uncertainty.'),('Begin indefinite nocturnal oxygen as a diagnostic test','Treatment response is not an appropriate replacement for objective assessment.')],
 'A negative home test does not complete every diagnostic pathway', '**AASM recommends PSG after a negative, inconclusive or technically inadequate home test.**',['Home recording may underestimate events.','Sleep time and the event types measured differ from full PSG.'], '**Review persistent symptoms and competing diagnoses.**',['Do not use reassurance to replace a needed assessment.','A laboratory study can characterize more complex respiratory and sleep findings.'],[['Home result','Negative but suspicion persists'],['Next test','PSG'],['Reason','Higher diagnostic characterization']],[DX],style='clinical_scenario')
q('Which patient is better assessed with polysomnography rather than a simple home OSA test?', 'A patient with suspected sleep-related hypoventilation and significant neuromuscular weakness',[
 ('An otherwise uncomplicated adult with classic OSA symptoms','Home testing can be suitable in an appropriate pathway.'),('An uncomplicated adult who can use the home device correctly','This alone does not require a laboratory study.'),('A low-comorbidity patient solely because they prefer their own bed','Preference is relevant but is not the physiological reason for PSG in the stated comparison.')],
 'Complex respiratory physiology requires a more complete study', '**Hypoventilation and neuromuscular disease are important reasons to prefer PSG.**',['CO2 assessment may be needed.','Other significant cardiopulmonary disease and chronic opioid exposure can also alter test selection.'], '**Match the test to the suspected disorder.**',['An OSA-only device can miss relevant nonobstructive abnormalities.','Integrate daytime gases and respiratory mechanics when indicated.'],[['Uncomplicated OSA suspicion','Home pathway may suffice'],['Hypoventilation suspicion','PSG-based evaluation'],['Reason','Broader physiological assessment']],[DX],style='clinical_scenario')
q('What is the main mechanism of CPAP treatment in OSA?', 'Pneumatic splinting of the upper airway',[
 ('Direct reversal of obesity by increasing calorie expenditure','CPAP is not a weight-loss treatment.'),('Permanent removal of pharyngeal tissue','It does not surgically alter anatomy.'),('Direct stimulation of erythropoietin','This is not the therapeutic mechanism.')],
 'CPAP prevents collapse while it is applied', '**Continuous positive pressure stabilizes a collapsible upper airway.**',['Benefit depends on use during sleep.','The appropriate pressure varies between patients.'], '**Optimize comfort and adherence.**',['Review mask fit, leak, dryness and residual events.','Education and early troubleshooting can improve effective use.'],[['Mechanism','Upper-airway splint'],['Requirement','Use during sleep'],['Follow-up','Comfort, adherence and residual burden']],[PA])
q('A sleepy patient with OSA uses CPAP for only 2 hours nightly because of mask leak and nasal dryness. What is the best initial approach?', 'Troubleshoot interface and humidification issues and review objective use and residual events',[
 ('Declare CPAP biologically ineffective without addressing use','Insufficient exposure and delivery problems can explain persistent symptoms.'),('Increase pressure to the maximum without checking leak','This may worsen intolerance without solving the problem.'),('Prescribe a stimulant as the sole response','Residual sleepiness should first prompt assessment of treatment adequacy and other causes.')],
 'Treatment failure can reflect poor delivery rather than an ineffective mechanism', '**Review the device data and patient experience together.**',['Leak can reduce effective treatment.','Nasal care, humidification and interface adjustment may improve tolerance.'], '**Reassess sleep duration and other causes of sleepiness.**',['Avoid assuming all symptoms are due to residual obstructive events.','Escalate the treatment plan if adequate use does not control disease.'],[['First review','Use, leak and residual events'],['Comfort','Interface and humidification'],['Persistent symptoms','Broader sleep and medical assessment']],[PA],style='clinical_scenario')
q('An adult with OSA cannot tolerate CPAP and prefers an alternative. Which option is supported in suitable patients?', 'A custom titratable mandibular advancement appliance with qualified dental and sleep follow-up',[
 ('A generic mouthguard without assessment as an equivalent proven option','Custom titration and follow-up are important.'),('Routine nocturnal sedatives to suppress arousals','They do not reliably correct obstruction and can worsen risk.'),('No further treatment assessment','Alternatives can be appropriate.')],
 'Oral appliances modify upper-airway mechanics', '**Mandibular advancement can reduce obstruction in selected OSA.**',['Efficacy and suitability depend on phenotype and dentition.','CPAP often produces greater event reduction, especially in severe disease.'], '**Confirm treatment effectiveness objectively.**',['Monitor dental and jaw adverse effects.','Continue sleep-clinical follow-up rather than assuming snoring reduction proves control.'],[['Device','Custom titratable appliance'],['Follow-up','Dental and sleep assessment'],['Confirmation','Objective effectiveness testing']],[OA],style='clinical_scenario')
q('What is the most appropriate counseling for a patient with untreated OSA and episodes of falling asleep while driving?', 'Avoid driving while sleepy and arrange prompt assessment and effective treatment under applicable local rules',[
 ('Open the window as a reliable substitute for treatment','This does not reliably prevent sleep-related crashes.'),('Daytime sleepiness is irrelevant if AHI is below 30','Driving risk is clinically important across numerical severity bands.'),('Only caffeine is needed before a long drive','It is not an adequate risk-management strategy.')],
 'Functional safety is a treatment priority', '**Sleepiness at the wheel is an immediate clinical concern.**',['Ask about near misses and occupational driving.','Explain the need for effective treatment and adequate sleep.'], '**Use local driving and reporting requirements.**',['Rules vary by jurisdiction and license type.','Document advice and arrange timely follow-up.'],[['Risk','Sleep-related crash'],['Immediate advice','Do not drive while sleepy'],['Longer-term','Effective treatment and local compliance']],[PA,DX],style='clinical_scenario')
q('Which definition best describes obesity hypoventilation syndrome?', 'Obesity with sleep-disordered breathing and awake PaCO2 at least 45 mmHg after excluding other hypoventilation causes',[
 ('Obesity and snoring with normal awake CO2 in every case','Awake hypercapnia is part of the definition.'),('Any transient nocturnal desaturation in a lean adult','This does not establish OHS.'),('Obesity plus an elevated bicarbonate alone','Bicarbonate is a screening clue, not the full definition.')],
 'OHS is more than obstructive events during sleep', '**The defining feature includes awake alveolar hypoventilation.**',['Obesity is generally BMI at least 30 kg/m².','Exclude alternative neuromuscular, chest-wall, drug and pulmonary causes.'], '**Assess the sleep phenotype and complications.**',['Severe OSA often coexists but is not the sole physiological issue.','Pulmonary hypertension and right-heart strain can occur.'],[['Body habitus','Obesity'],['Daytime gas','PaCO2 ≥45 mmHg'],['Requirement','Exclude other causes']],[OH])
q('An obese adult with sleep-disordered breathing has low-to-moderate clinical suspicion for OHS and serum bicarbonate 24 mmol/L. Which interpretation follows ATS guidance?', 'OHS is unlikely, and an ABG may be avoidable in this low-probability setting',[
 ('The result confirms OHS','A low bicarbonate does not establish chronic hypercapnia.'),('The same rule excludes OHS even with very high clinical suspicion','High suspicion warrants direct PaCO2 measurement.'),('Bicarbonate is irrelevant to any OHS screening strategy','It can be useful in the specified population.')],
 'Use the bicarbonate screen only in its intended probability range', '**A value below 27 mmol/L helps exclude OHS when pretest suspicion is not high.**',['Renal compensation for chronic CO2 elevation often raises bicarbonate.','Other causes of bicarbonate change can confound interpretation.'], '**Measure arterial CO2 when suspicion is high or the screen is positive.**',['A value at least 27 is not diagnostic by itself.','Use gases and exclusion of alternative causes to establish OHS.'],[['Low suspicion and HCO3 <27','OHS unlikely'],['HCO3 ≥27','Assess PaCO2'],['High suspicion','Measure PaCO2 directly']],[OH],style='clinical_scenario')
q('A stable ambulatory patient has OHS and severe coexisting OSA. What is the ATS-preferred initial PAP modality in most such patients?', 'CPAP',[
 ('NIV is mandatory as first-line therapy for every stable OHS patient','The severe-OSA phenotype often starts with CPAP.'),('Oxygen alone without PAP','This does not correct the obstructive and hypoventilation mechanism.'),('No treatment until a hospital admission occurs','Stable OHS still warrants treatment.')],
 'The OHS sleep phenotype influences initial support', '**ATS favors CPAP first in stable ambulatory OHS with severe OSA.**',['NIV may be needed for inadequate response or a different phenotype.','Assess adherence and physiological response after initiation.'], '**Combine PAP with weight-management care.**',['Monitor awake gases and nocturnal breathing when appropriate.','Do not continue an ineffective mode without reassessment.'],[['Stable OHS plus severe OSA','CPAP first in most'],['Inadequate response / other phenotype','Consider NIV'],['Parallel care','Weight management and follow-up']],[OH],style='clinical_scenario')
q('A patient hospitalized with hypercapnic respiratory failure is strongly suspected of having OHS. After stabilization, what discharge strategy does ATS suggest while definitive testing is arranged?', 'NIV pending timely outpatient diagnostic evaluation and PAP titration',[
 ('No support until testing many months later','This leaves a high-risk interval untreated.'),('Oxygen alone as a universal replacement for ventilatory support','It may not correct hypoventilation.'),('Assume OHS is cured because the acute pH normalized','The underlying disorder may persist.')],
 'The post-hospital interval carries risk', '**Temporary NIV can bridge to formal diagnosis and titration.**',['Arrange the outpatient work-up promptly, ideally within two to three months.','This is not a substitute for completing the assessment.'], '**Reassess the long-term modality after phenotype clarification.**',['Some stable severe-OSA patients can later use CPAP.','Review adherence, gases and recurrence risk.'],[['Discharge bridge','NIV'],['Next step','Sleep evaluation and titration'],['Long-term','Individualized mode after assessment']],[OH],style='clinical_scenario')
q('Which sustained weight-loss magnitude does the 2019 ATS OHS guideline identify as more likely to achieve resolution of hypoventilation?', 'About 25–30% of body weight',[
 ('About 1% in every patient','That is not the magnitude identified by the guideline.'),('Any overnight water-weight change','This is not sustained loss of adiposity.'),('Weight loss has no role once PAP is started','PAP and weight treatment address complementary issues.')],
 'Substantial durable weight loss can modify the underlying mechanical and metabolic burden', '**ATS identifies sustained 25–30% loss as a target associated with greater likelihood of OHS resolution.**',['Bariatric intervention may achieve this in suitable patients.','Medical weight-management options continue to evolve.'], '**Continue PAP until objective reassessment supports a change.**',['Do not stop support solely because some weight has been lost.','Recheck gas exchange and sleep-disordered breathing after meaningful change.'],[['Target in guideline','Sustained 25–30%'],['Treatment','Individual weight-management strategy'],['PAP withdrawal','Requires reassessment']],[OH])
q('Which adult population matches the US OSA indication for tirzepatide?', 'Adults with obesity and moderate-to-severe obstructive sleep apnea',[
 ('Every person with primary central sleep apnea regardless of BMI','That is not the labeled OSA population.'),('Children with isolated snoring as a universal indication','The stated indication is in adults with a defined OSA/obesity phenotype.'),('Lean adults with any sleep complaint','This is not the approved population.')],
 'A weight-directed drug now has a defined OSA indication', '**FDA approval is for moderate-to-severe OSA in adults with obesity.**',['It is used with reduced-calorie diet and increased physical activity.','Benefit does not imply an immediate substitute for all existing PAP treatment.'], '**Review contraindications and monitor the overall plan.**',['Use the current prescribing information.','Reassess OSA objectively before reducing established respiratory support.'],[['Population','Adult obesity plus moderate/severe OSA'],['Adjuncts','Diet and activity'],['Follow-up','Weight, tolerability and OSA control']],[TZ])
q('During a sleep study, repeated apneas occur without thoracic or abdominal effort. Which event type is present?', 'Central apnea',[
 ('Obstructive apnea','Effort usually persists against the obstruction.'),('Primary snoring','Snoring does not define absent respiratory effort.'),('Isolated periodic limb movement','That is a separate motor event.')],
 'Central events reflect absent or reduced respiratory drive', '**Airflow cessation occurs together with absent inspiratory effort.**',['Heart failure, opioids and other conditions can contribute.','The event pattern and underlying cause guide treatment.'], '**Assess more than the event label.**',['Review cardiac function, medications and altitude exposure.','Optimize the associated disease and choose a supported treatment strategy.'],[['Central','No airflow and no effort'],['Obstructive','Effort persists'],['Management','Cause-specific assessment']],[CS])
q('A patient with heart failure has crescendo–decrescendo ventilation alternating with central apneas. Which pattern is most likely?', 'Cheyne-Stokes breathing',[
 ('Pure obstructive apnea with continuous effort','The periodic ventilation and absent-effort pauses suggest a central pattern.'),('Kussmaul breathing','This is sustained deep ventilation, classically with metabolic acidosis, rather than periodic central pauses.'),('Isolated stridor','This is an upper-airway sound, not the described ventilatory cycle.')],
 'Periodic breathing can reflect unstable ventilatory control', '**Cheyne-Stokes breathing has a waxing and waning pattern with central pauses.**',['Circulatory delay and chemoreflex instability can contribute in heart failure.','Not every patient with this pattern has the same treatment indication.'], '**Optimize the underlying cardiac condition and assess symptoms and sleep physiology.**',['Review medications and oxygenation.','Advanced device decisions require attention to EF and the specific device evidence.'],[['Pattern','Crescendo–decrescendo ventilation'],['Pause','Central apnea'],['Context','Often heart failure or other central-control disease']],[CS],style='clinical_scenario')
q('What is the most appropriate approach to adaptive servo-ventilation in a patient with central sleep apnea and reduced-EF heart failure?', 'Specialist, device-specific assessment with optimized heart-failure care and attention to current safety guidance',[
 ('Assume all ASV devices are universally safe and mortality-reducing','Trial and device-specific safety concerns preclude that conclusion.'),('Apply an old blanket statement without checking the device or updated evidence','The 2025 guidance and device labeling require a more specific assessment.'),('Start a device without measuring EF or reviewing the underlying disease','Cardiac phenotype is central to the decision.')],
 'Central-apnea device decisions require a careful evidence match', '**The SERVE-HF safety signal makes EF and device-specific evidence important.**',['Newer studies and the 2025 AASM guideline require a nuanced interpretation.','This is not a routine unsupervised device-selection decision.'], '**Use an experienced service and shared decision-making.**',['Optimize the contributing disease first.','Check current device contraindications and arrange close follow-up when treatment is considered.'],[['Key phenotype','Heart failure and EF'],['Key evidence','Device and trial population'],['Care','Experienced specialist assessment']],[CS])

if __name__=='__main__':finalize('Respiratory system',10,'Sleep-disordered Breathing','resp-sleep',rows,20)
